import sys
from bisect import bisect_right

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    P = [0]
    for i in range(n):
        P.append(P[-1] + int(data[2 + i]))
    vals = sorted(set(P))
    m = len(vals)
    INF = float('inf')
    tree = [INF] * (m + 1)

    def add(idx, v):
        r = m - idx
        while r <= m:
            if v < tree[r]:
                tree[r] = v
            r += r & -r

    def query(pos):
        r = m - pos
        res = INF
        while r > 0:
            if tree[r] < res:
                res = tree[r]
            r -= r & -r
        return res

    from bisect import bisect_left
    add(bisect_left(vals, 0), 0)
    best = None
    for i in range(1, n + 1):
        pos = bisect_right(vals, P[i] - k)
        if pos < m:
            low = query(pos)
            if low != INF:
                s = P[i] - low
                if best is None or s > best:
                    best = s
        add(bisect_left(vals, P[i]), P[i])
    print(best if best is not None else 'NONE')

